const o=JSON.parse('{"workId":"mo-zi","chapter":{"id":"mo-zi_ch-49","workId":"mo-zi","order":49,"title":"魯問","difficulty":5,"estimatedMinutes":15,"passageIds":["mo-zi_ch-49_p-1","mo-zi_ch-49_p-2","mo-zi_ch-49_p-3","mo-zi_ch-49_p-4","mo-zi_ch-49_p-5","mo-zi_ch-49_p-6","mo-zi_ch-49_p-7","mo-zi_ch-49_p-8","mo-zi_ch-49_p-9","mo-zi_ch-49_p-10","mo-zi_ch-49_p-11","mo-zi_ch-49_p-12","mo-zi_ch-49_p-13","mo-zi_ch-49_p-14","mo-zi_ch-49_p-15","mo-zi_ch-49_p-16","mo-zi_ch-49_p-17","mo-zi_ch-49_p-18","mo-zi_ch-49_p-19","mo-zi_ch-49_p-20","mo-zi_ch-49_p-21","mo-zi_ch-49_p-22"],"tags":["墨家","墨子"]},"passages":[{"id":"mo-zi_ch-49_p-1","chapterId":"mo-zi_ch-49","order":1,"canonicalText":"魯君謂子墨子曰：「吾恐齊之攻我也，可救乎？」子墨子曰：「可。昔者，三代之聖王禹湯文武，百里之諸侯也，說忠行義，取天下。三代之暴王桀紂幽厲，讎怨行暴，失天下。吾願主君，之上者尊天事鬼，下者愛利百姓，厚為皮幣，卑辭令，亟遍禮四鄰諸侯，敺國而以事齊，患可救也，非此，顧無可為者。」","sentenceIds":["mo-zi_ch-49_p-1_s-1","mo-zi_ch-49_p-1_s-2","mo-zi_ch-49_p-1_s-3","mo-zi_ch-49_p-1_s-4","mo-zi_ch-49_p-1_s-5","mo-zi_ch-49_p-1_s-6"],"sourceRefs":[{"label":"《墨子》—中國哲學書電子化計劃","edition":"孫詒讓《墨子閒詁》本","location":"https://ctext.org/mozi/zh","accessedAt":"2026-08-31"},{"label":"《墨子》—維基文庫","edition":"四部叢刊景明正統道藏本","location":"https://zh.wikisource.org/zh-hant/墨子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"魯君謂墨子先生親自教導說道：吾恐齊的攻我啊，可救乎？墨子先生親自教導說道：可。昔日，三代的聖王禹湯文武，百里的諸侯啊，推理說理忠行義，取天下。三代的暴王桀紂幽厲，讎怨行暴，失天下。吾願主君，的上的人尊天事鬼，下的人愛利百姓，厚為皮幣，卑判斷命題令，亟遍禮四鄰諸侯，敺國而且以事齊，患可救啊，絕不是此，顧無可為的人。","analysis":"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈魯問〉（第 1 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「魯君謂子墨子曰：「吾恐齊之攻我也，可救乎」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「魯君謂子墨子曰：「吾恐齊之攻我也，可救乎？」子墨子曰……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。","historicalContext":"","keywords":[]}},{"id":"mo-zi_ch-49_p-2","chapterId":"mo-zi_ch-49","order":2,"canonicalText":"齊將伐魯，子墨子謂項子牛曰：「伐魯，齊之大過也。昔者，吳王東伐越，棲諸會稽，西伐楚，葆昭王於隨。北伐齊，取國子以歸於吳。諸侯報其讎，百姓苦其勞，而弗為用，是以國為虛戾，身為刑戮也。昔者，智伯伐范氏與中行氏，兼三晉之地，諸侯報其讎，百姓苦其勞，而弗為用，是以國為虛戾，身為刑戮用是也。故大國之攻小國也，是交相賊也，過必反於國。」","sentenceIds":["mo-zi_ch-49_p-2_s-1","mo-zi_ch-49_p-2_s-2","mo-zi_ch-49_p-2_s-3","mo-zi_ch-49_p-2_s-4","mo-zi_ch-49_p-2_s-5","mo-zi_ch-49_p-2_s-6","mo-zi_ch-49_p-2_s-7"],"sourceRefs":[{"label":"《墨子》—中國哲學書電子化計劃","edition":"孫詒讓《墨子閒詁》本","location":"https://ctext.org/mozi/zh","accessedAt":"2026-08-31"},{"label":"《墨子》—維基文庫","edition":"四部叢刊景明正統道藏本","location":"https://zh.wikisource.org/zh-hant/墨子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"齊將伐魯，子墨子謂項子牛說道：伐魯，齊的大過啊。昔日，吳王東伐越，棲諸會稽，西伐楚，葆昭王於隨。北伐齊，取國子以歸於吳。諸侯報他的讎，百姓苦他的勞，而且弗為用，是以國為虛戾，身為刑戮啊。昔日，智伯伐范氏與中行氏，兼三晉的地，諸侯報他的讎，百姓苦他的勞，而且弗為用，是以國為虛戾，身為刑戮用是啊。所以大國的攻小國啊，是交相賊啊，過必反於國。","analysis":"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈魯問〉（第 2 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「齊將伐魯，子墨子謂項子牛曰：「伐魯，齊之大過也」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「齊將伐魯，子墨子謂項子牛曰：「伐魯，齊之大過也。昔者……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。","historicalContext":"","keywords":[]}},{"id":"mo-zi_ch-49_p-3","chapterId":"mo-zi_ch-49","order":3,"canonicalText":"子墨子見齊大王曰：「今有刀於此，試之人頭，倅然斷之，可謂利乎？」大王曰：「利。」子墨子曰：「多試之人頭，倅然斷之，可謂利乎？」大王曰：「利。」子墨子曰：「刀則利矣，孰將受其不祥？」大王曰：「刀受其利，試者受其不祥。」子墨子曰：「並國覆軍，賊殺百姓，孰將受其不祥？」大王俯仰而思之曰：「我受其不祥。」","sentenceIds":["mo-zi_ch-49_p-3_s-1","mo-zi_ch-49_p-3_s-2","mo-zi_ch-49_p-3_s-3","mo-zi_ch-49_p-3_s-4","mo-zi_ch-49_p-3_s-5","mo-zi_ch-49_p-3_s-6","mo-zi_ch-49_p-3_s-7","mo-zi_ch-49_p-3_s-8","mo-zi_ch-49_p-3_s-9"],"sourceRefs":[{"label":"《墨子》—中國哲學書電子化計劃","edition":"孫詒讓《墨子閒詁》本","location":"https://ctext.org/mozi/zh","accessedAt":"2026-08-31"},{"label":"《墨子》—維基文庫","edition":"四部叢刊景明正統道藏本","location":"https://zh.wikisource.org/zh-hant/墨子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"子墨子見齊大王說道：今有刀於此，試的人頭，倅然斷的，可謂利乎？大王說道：利。墨子先生親自教導說道：多試的人頭，倅然斷的，可謂利乎？墨子先生親自教導說道：刀則利矣，孰將受他的不祥？大王說道：刀受他的利，試的人受他的不祥。墨子先生親自教導說道：並國覆軍，賊殺百姓，孰將受他的不祥？大王俯仰而且思說道：我受他的不祥。","analysis":"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈魯問〉（第 3 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「子墨子見齊大王曰：「今有刀於此，試之人頭，倅然斷之，可謂利乎」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「子墨子見齊大王曰：「今有刀於此，試之人頭，倅然斷之，……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。","historicalContext":"","keywords":[]}},{"id":"mo-zi_ch-49_p-4","chapterId":"mo-zi_ch-49","order":4,"canonicalText":"魯陽文君將攻鄭，子墨子聞而止之，謂陽文君曰：「今使魯四境之內，大都攻其小都，大家伐其小家，殺其人民，取其牛馬狗豕布帛米粟貨財，則何若？」魯陽文君曰：「魯四境之內，皆寡人之臣也。今大都攻其小都，大家伐其小家，奪之貨財，則寡人必將厚罰之。」子墨子曰：「夫天之兼有天下也，亦猶君之有四境之內也。今舉兵將以攻鄭，天誅亓不至乎？」魯陽文君曰：「先生何止我攻鄭也？我攻鄭，順於天之志。鄭人三世殺其父，天加誅焉，使三年不全。我將助天誅也。」子墨子曰：「鄭人三世殺其父而天加誅焉，使三年不全。天誅足矣，今又舉兵將以攻鄭，曰『吾攻鄭也，順於天之志』。譬有人於此，其子強梁不材，故其父笞之，其鄰家之父舉木而擊之，曰：『吾擊之也，順於其父之志』，則豈不悖哉？」","sentenceIds":["mo-zi_ch-49_p-4_s-1","mo-zi_ch-49_p-4_s-2","mo-zi_ch-49_p-4_s-3","mo-zi_ch-49_p-4_s-4","mo-zi_ch-49_p-4_s-5","mo-zi_ch-49_p-4_s-6","mo-zi_ch-49_p-4_s-7","mo-zi_ch-49_p-4_s-8","mo-zi_ch-49_p-4_s-9","mo-zi_ch-49_p-4_s-10","mo-zi_ch-49_p-4_s-11","mo-zi_ch-49_p-4_s-12","mo-zi_ch-49_p-4_s-13"],"sourceRefs":[{"label":"《墨子》—中國哲學書電子化計劃","edition":"孫詒讓《墨子閒詁》本","location":"https://ctext.org/mozi/zh","accessedAt":"2026-08-31"},{"label":"《墨子》—維基文庫","edition":"四部叢刊景明正統道藏本","location":"https://zh.wikisource.org/zh-hant/墨子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"魯陽文君將攻鄭，子墨子聞而且止的，謂陽文君說道：今使魯四境的內，大都攻他的小都，大家伐他的小家，殺他的人民，取他的牛馬狗豕布帛米粟貨財，則何若？魯陽文君說道：魯四境的內，皆寡人的臣啊。今大都攻他的小都，大家伐他的小家，奪的貨財，則寡人必將厚罰的。墨子先生親自教導說道：夫天的兼有天下啊，亦猶君的有四境的內啊。今舉兵將以攻鄭，天誅亓不至乎？魯陽文君說道：先生何止我攻鄭啊？我攻鄭，順於天的志。鄭人三世殺他的父，天加誅焉，使三年不全。我將助天誅啊。墨子先生親自教導說道：鄭人三世殺他的父而且天加誅焉，使三年不全。天誅足矣，今又舉兵將以攻鄭，說道：吾攻鄭啊，順於天的志。譬有人於此，他的子強梁不材，所以他的父笞的，他的鄰家的父舉木而且擊的，說道：吾擊的啊，順於他的父的志，則豈不悖哉？","analysis":"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈魯問〉（第 4 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「魯陽文君將攻鄭，子墨子聞而止之，謂陽文君曰：「今使魯四境之內，大都攻其小都，大家伐其小家，殺其人民，取其牛馬狗豕布帛米粟貨財，則何若」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「魯陽文君將攻鄭，子墨子聞而止之，謂陽文君曰：「今使魯……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。","historicalContext":"","keywords":[]}},{"id":"mo-zi_ch-49_p-5","chapterId":"mo-zi_ch-49","order":5,"canonicalText":"子墨子謂魯陽文君曰：「攻其鄰國，殺其民人，取其牛馬、粟米、貨財，則書之於竹帛，鏤之於金石，以為銘於鍾鼎，傳遺後世子孫曰：『莫若我多。』今賤人也，亦攻其鄰家，殺其人民，取其狗豕食糧衣裘，亦書之竹帛，以為銘於席豆，以遺後世子孫曰：『莫若我多。』亓可乎？」魯陽文君曰：「然吾以子之言觀之，則天下之所謂可者，未必然也。」","sentenceIds":["mo-zi_ch-49_p-5_s-1","mo-zi_ch-49_p-5_s-2","mo-zi_ch-49_p-5_s-3","mo-zi_ch-49_p-5_s-4","mo-zi_ch-49_p-5_s-5"],"sourceRefs":[{"label":"《墨子》—中國哲學書電子化計劃","edition":"孫詒讓《墨子閒詁》本","location":"https://ctext.org/mozi/zh","accessedAt":"2026-08-31"},{"label":"《墨子》—維基文庫","edition":"四部叢刊景明正統道藏本","location":"https://zh.wikisource.org/zh-hant/墨子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"子墨子謂魯陽文君說道：攻他的鄰國，殺他的民人，取他的牛馬、粟米、貨財，則書的於竹帛，鏤的於金石，以為銘於鍾鼎，傳遺後世子孫說道：莫若我多。今賤人啊，亦攻他的鄰家，殺他的人民，取他的狗豕食糧衣裘，亦書的竹帛，以為銘於席豆，以遺後世子孫說道：莫若我多。亓可乎？魯陽文君說道：然吾以子的言觀的，則天下的所謂可的人，未必然啊。","analysis":"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈魯問〉（第 5 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「子墨子謂魯陽文君曰：「攻其鄰國，殺其民人，取其牛馬、粟米、貨財，則書之於竹帛，鏤之於金石，以為銘於鍾鼎，傳遺後世子孫曰：『莫若我多」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「子墨子謂魯陽文君曰：「攻其鄰國，殺其民人，取其牛馬、……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。","historicalContext":"","keywords":[]}},{"id":"mo-zi_ch-49_p-6","chapterId":"mo-zi_ch-49","order":6,"canonicalText":"子墨子為魯陽文君曰：「世俗之君子，皆知小物而不知大物。今有人於此，竊一犬一彘則謂之不仁，竊一國一都則以為義。譬猶小視白謂之白，大視白則謂之黑。是故世俗之君子，知小物而不知大物者，此若言之謂也。」","sentenceIds":["mo-zi_ch-49_p-6_s-1","mo-zi_ch-49_p-6_s-2","mo-zi_ch-49_p-6_s-3","mo-zi_ch-49_p-6_s-4","mo-zi_ch-49_p-6_s-5"],"sourceRefs":[{"label":"《墨子》—中國哲學書電子化計劃","edition":"孫詒讓《墨子閒詁》本","location":"https://ctext.org/mozi/zh","accessedAt":"2026-08-31"},{"label":"《墨子》—維基文庫","edition":"四部叢刊景明正統道藏本","location":"https://zh.wikisource.org/zh-hant/墨子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"子墨子為魯陽文君說道：世俗的君子，皆知小物而且不知大物。今有人於此，竊一犬一彘則謂的不仁，竊一國一都則以為義。譬猶小視白謂的白，大視白則謂的黑。正因為如此世俗的君子，知小物而且不知大物的人，此若言的謂啊。","analysis":"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈魯問〉（第 6 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「子墨子為魯陽文君曰：「世俗之君子，皆知小物而不知大物」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「子墨子為魯陽文君曰：「世俗之君子，皆知小物而不知大物……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。","historicalContext":"","keywords":[]}},{"id":"mo-zi_ch-49_p-7","chapterId":"mo-zi_ch-49","order":7,"canonicalText":"魯陽文君語子墨子曰：「楚之南有啖人之國者橋，其國之長子生，則鮮而食之，謂之宜弟。美，則以遺其君，君喜則賞其父。豈不惡俗哉？」子墨子曰：「雖中國之俗，亦猶是也。殺其父而賞其子，何以異食其子而賞其父者哉？苟不用仁義，何以非夷人食其子也？」","sentenceIds":["mo-zi_ch-49_p-7_s-1","mo-zi_ch-49_p-7_s-2","mo-zi_ch-49_p-7_s-3","mo-zi_ch-49_p-7_s-4","mo-zi_ch-49_p-7_s-5","mo-zi_ch-49_p-7_s-6","mo-zi_ch-49_p-7_s-7"],"sourceRefs":[{"label":"《墨子》—中國哲學書電子化計劃","edition":"孫詒讓《墨子閒詁》本","location":"https://ctext.org/mozi/zh","accessedAt":"2026-08-31"},{"label":"《墨子》—維基文庫","edition":"四部叢刊景明正統道藏本","location":"https://zh.wikisource.org/zh-hant/墨子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"魯陽文君語墨子先生親自教導說道：楚的南有啖人的國的人橋，他的國的長子生，則鮮而且食的，謂的宜弟。美，則以遺他的君，君喜則賞他的父。豈不惡俗哉？墨子先生親自教導說道：雖中國的俗，亦猶是啊。殺他的父而且賞他的子，何以異食他的子而且賞他的父的人哉？苟不用仁義，何以絕不是夷人食他的子啊？","analysis":"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈魯問〉（第 7 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「魯陽文君語子墨子曰：「楚之南有啖人之國者橋，其國之長子生，則鮮而食之，謂之宜弟」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「魯陽文君語子墨子曰：「楚之南有啖人之國者橋，其國之長……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。","historicalContext":"","keywords":[]}},{"id":"mo-zi_ch-49_p-8","chapterId":"mo-zi_ch-49","order":8,"canonicalText":"魯君之嬖人死，魯君為之誄，魯人因說而用之。子墨子聞之曰：「誄者，道死人之志也，今因說而用之，是猶以來首從服也。」","sentenceIds":["mo-zi_ch-49_p-8_s-1","mo-zi_ch-49_p-8_s-2","mo-zi_ch-49_p-8_s-3"],"sourceRefs":[{"label":"《墨子》—中國哲學書電子化計劃","edition":"孫詒讓《墨子閒詁》本","location":"https://ctext.org/mozi/zh","accessedAt":"2026-08-31"},{"label":"《墨子》—維基文庫","edition":"四部叢刊景明正統道藏本","location":"https://zh.wikisource.org/zh-hant/墨子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"魯君的嬖人死，魯君為的誄，魯人因推理說理而且用的。子墨子聞說道：誄的人，道死人的志啊，今因推理說理而且用的，是猶以來首從服啊。","analysis":"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈魯問〉（第 8 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「魯君之嬖人死，魯君為之誄，魯人因說而用之」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「魯君之嬖人死，魯君為之誄，魯人因說而用之。子墨子聞之……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。","historicalContext":"","keywords":[]}},{"id":"mo-zi_ch-49_p-9","chapterId":"mo-zi_ch-49","order":9,"canonicalText":"魯陽文君謂子墨子曰：「有語我以忠臣者，令之俯則俯，令之仰則仰，處則靜，呼則應，可謂忠臣乎？」子墨子曰：「令之俯則俯，令之仰則仰，是似景也。處則靜，呼則應，是似響也。君將何得於景與響哉？若以翟之所謂忠臣者，上有過則微之以諫，己有善，則訪之上，而無敢以告。外匡其邪，而入其善，尚同而無下比，是以美善在上，而怨讎在下，安樂在上，而憂慼在臣。此翟之所謂忠臣者也。」","sentenceIds":["mo-zi_ch-49_p-9_s-1","mo-zi_ch-49_p-9_s-2","mo-zi_ch-49_p-9_s-3","mo-zi_ch-49_p-9_s-4","mo-zi_ch-49_p-9_s-5","mo-zi_ch-49_p-9_s-6","mo-zi_ch-49_p-9_s-7","mo-zi_ch-49_p-9_s-8"],"sourceRefs":[{"label":"《墨子》—中國哲學書電子化計劃","edition":"孫詒讓《墨子閒詁》本","location":"https://ctext.org/mozi/zh","accessedAt":"2026-08-31"},{"label":"《墨子》—維基文庫","edition":"四部叢刊景明正統道藏本","location":"https://zh.wikisource.org/zh-hant/墨子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"魯陽文君謂墨子先生親自教導說道：有語我以忠臣的人，令的俯則俯，令的仰則仰，處則靜，呼則應，可謂忠臣乎？墨子先生親自教導說道：令的俯則俯，令的仰則仰，是似景啊。處則靜，呼則應，是似響啊。君將何得於景與響哉？若以翟的所謂忠臣的人，上有過則微的以諫，己有善，則訪的上，而且無敢以告。外匡他的邪，而且入他的善，上下一心一統政令而且無下比，是以美善在上，而且怨讎在下，安樂在上，而且憂慼在臣。此翟的所謂忠臣的人啊。","analysis":"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈魯問〉（第 9 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「魯陽文君謂子墨子曰：「有語我以忠臣者，令之俯則俯，令之仰則仰，處則靜，呼則應，可謂忠臣乎」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「魯陽文君謂子墨子曰：「有語我以忠臣者，令之俯則俯，令……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。","historicalContext":"","keywords":[]}},{"id":"mo-zi_ch-49_p-10","chapterId":"mo-zi_ch-49","order":10,"canonicalText":"魯君謂子墨子曰：「我有二子，一人者好學，一人者好分人財，孰以為太子而可？」子墨子曰：「未可知也，或所為賞與為是也。魡者之恭，非為魚賜也；餌鼠以蟲，非愛之也。吾願主君之合其志功而觀焉。」","sentenceIds":["mo-zi_ch-49_p-10_s-1","mo-zi_ch-49_p-10_s-2","mo-zi_ch-49_p-10_s-3","mo-zi_ch-49_p-10_s-4","mo-zi_ch-49_p-10_s-5","mo-zi_ch-49_p-10_s-6"],"sourceRefs":[{"label":"《墨子》—中國哲學書電子化計劃","edition":"孫詒讓《墨子閒詁》本","location":"https://ctext.org/mozi/zh","accessedAt":"2026-08-31"},{"label":"《墨子》—維基文庫","edition":"四部叢刊景明正統道藏本","location":"https://zh.wikisource.org/zh-hant/墨子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"魯君謂墨子先生親自教導說道：我有二子，一人的人好學，一人的人好分人財，孰以為太子而且可？墨子先生親自教導說道：未可知啊，或所為賞與為是啊。魡的人的恭，絕不是為魚賜啊；餌鼠以蟲，絕不是愛的啊。吾願主君的合他的志功而且觀焉。","analysis":"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈魯問〉（第 10 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「魯君謂子墨子曰：「我有二子，一人者好學，一人者好分人財，孰以為太子而可」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「魯君謂子墨子曰：「我有二子，一人者好學，一人者好分人……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。","historicalContext":"","keywords":[]}},{"id":"mo-zi_ch-49_p-11","chapterId":"mo-zi_ch-49","order":11,"canonicalText":"魯人有因子墨子而學其子者，其子戰而死，其父讓子墨子。子墨子曰：子欲學子之子，今學成矣，戰而死，而子慍，而猶欲糶，糶讎，則慍也。豈不費哉？」","sentenceIds":["mo-zi_ch-49_p-11_s-1","mo-zi_ch-49_p-11_s-2","mo-zi_ch-49_p-11_s-3","mo-zi_ch-49_p-11_s-4"],"sourceRefs":[{"label":"《墨子》—中國哲學書電子化計劃","edition":"孫詒讓《墨子閒詁》本","location":"https://ctext.org/mozi/zh","accessedAt":"2026-08-31"},{"label":"《墨子》—維基文庫","edition":"四部叢刊景明正統道藏本","location":"https://zh.wikisource.org/zh-hant/墨子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"魯人有因子墨子而且學他的子的人，他的子戰而且死，他的父讓子墨子。墨子先生親自教導說道：子欲學子的子，今學成矣，戰而且死，而且子慍，而且猶欲糶，糶讎，則慍啊。豈不費哉？","analysis":"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈魯問〉（第 11 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「魯人有因子墨子而學其子者，其子戰而死，其父讓子墨子」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「魯人有因子墨子而學其子者，其子戰而死，其父讓子墨子。……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。","historicalContext":"","keywords":[]}},{"id":"mo-zi_ch-49_p-12","chapterId":"mo-zi_ch-49","order":12,"canonicalText":"魯之南鄙人，有吳慮者，冬陶夏耕，自比於舜。子墨子聞而見之。吳慮謂子墨子「義耳義耳，焉用言之哉？」子墨子曰：「子之所謂義者，亦有力以勞人，有財以分人乎？」吳慮曰：「有。」子墨子曰：「翟嘗計之矣。翟慮耕而食天下之人矣，盛，然後當一農之耕，分諸天下，不能人得一升粟。籍而以為得一升粟，其不能飽天下之飢者，既可睹矣。翟慮織而衣天下之人矣，盛，然後當一婦人之織，分諸天下，不能人得尺布。籍而以為得尺布，其不能煖天下之寒者，既可睹矣。翟慮被堅執銳救諸侯之患，盛，然後當一夫之戰，一夫之戰其不御三軍，既可睹矣。翟以為不若誦先王之道，而求其說，通聖人之言，而察其辭，上說王公大人，次匹夫徒步之士。王公大人用吾言，國必治；匹夫徒步之士用吾言，行必脩。故翟以為雖不耕而食飢，不織而衣寒，功賢於耕而食之、織而衣之者也。故翟以為雖不耕織乎，而功賢於耕織也。」吳慮謂子墨子曰：「義耳義耳，焉用言之哉？」子墨子曰：「籍設而天下不知耕，教人耕，與不教人耕而獨耕者，其功孰多？」吳慮曰：「教人耕者其功多。」子墨子曰：「籍設而攻不義之國，鼓而使眾進戰，與不鼓而使眾進戰，而獨進戰者，其功孰多？」吳慮曰：「鼓而進眾者其功多。」子墨子曰：「天下匹夫徒步之士，少知義而教天下以義者，功亦多，何故弗言也？若得鼓而進於義，則吾義豈不益進哉？」","sentenceIds":["mo-zi_ch-49_p-12_s-1","mo-zi_ch-49_p-12_s-2","mo-zi_ch-49_p-12_s-3","mo-zi_ch-49_p-12_s-4","mo-zi_ch-49_p-12_s-5","mo-zi_ch-49_p-12_s-6","mo-zi_ch-49_p-12_s-7","mo-zi_ch-49_p-12_s-8","mo-zi_ch-49_p-12_s-9","mo-zi_ch-49_p-12_s-10","mo-zi_ch-49_p-12_s-11","mo-zi_ch-49_p-12_s-12","mo-zi_ch-49_p-12_s-13","mo-zi_ch-49_p-12_s-14","mo-zi_ch-49_p-12_s-15","mo-zi_ch-49_p-12_s-16","mo-zi_ch-49_p-12_s-17","mo-zi_ch-49_p-12_s-18","mo-zi_ch-49_p-12_s-19","mo-zi_ch-49_p-12_s-20","mo-zi_ch-49_p-12_s-21","mo-zi_ch-49_p-12_s-22","mo-zi_ch-49_p-12_s-23","mo-zi_ch-49_p-12_s-24"],"sourceRefs":[{"label":"《墨子》—中國哲學書電子化計劃","edition":"孫詒讓《墨子閒詁》本","location":"https://ctext.org/mozi/zh","accessedAt":"2026-08-31"},{"label":"《墨子》—維基文庫","edition":"四部叢刊景明正統道藏本","location":"https://zh.wikisource.org/zh-hant/墨子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"魯的南鄙人，有吳慮的人，冬陶夏耕，自比於舜。子墨子聞而且見的。吳慮謂子墨子義耳義耳，焉用言的哉？墨子先生親自教導說道：子的所謂義的人，亦有力以勞人，有財以分人乎？吳慮說道：有。墨子先生親自教導說道：翟嘗計的矣。翟慮耕而且食天下的人矣，盛，然後當一農的耕，分諸天下，不能人得一升粟。籍而且以為得一升粟，他的不能飽天下的飢的人，既可睹矣。翟慮織而且衣天下的人矣，盛，然後當一婦人的織，分諸天下，不能人得尺布。籍而且以為得尺布，他的不能煖天下的寒的人，既可睹矣。翟慮被堅執銳救諸侯的患，盛，然後當一夫的戰，一夫的戰他的不御三軍，既可睹矣。翟以為不若誦先王的道，而且求他的推理說理，通聖人的言，而且察他的判斷命題，上推理說理王公大人，次匹夫徒步的士。王公大人用吾言，國必治；匹夫徒步的士用吾言，行必脩。所以翟以為雖不耕而且食飢，不織而且衣寒，功賢於耕而且食的、織而且衣的的人啊。所以翟以為雖不耕織乎，而且功賢於耕織啊。吳慮謂墨子先生親自教導說道：義耳義耳，焉用言的哉？墨子先生親自教導說道：籍設而且天下不知耕，教人耕，與不教人耕而且獨耕的人，他的功孰多？吳慮說道：教人耕的人他的功多。墨子先生親自教導說道：籍設而且攻不義的國，鼓而且使眾進戰，與不鼓而且使眾進戰，而且獨進戰的人，他的功孰多？吳慮說道：鼓而且進眾的人他的功多。墨子先生親自教導說道：天下匹夫徒步的士，少知義而且教天下以義的人，功亦多，何所以弗言啊？若得鼓而且進於義，則吾義豈不益進哉？","analysis":"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈魯問〉（第 12 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「魯之南鄙人，有吳慮者，冬陶夏耕，自比於舜」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「魯之南鄙人，有吳慮者，冬陶夏耕，自比於舜。子墨子聞而……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。","historicalContext":"","keywords":[]}},{"id":"mo-zi_ch-49_p-13","chapterId":"mo-zi_ch-49","order":13,"canonicalText":"子墨子游公尚過於越。公尚過說越王，越王大說，謂公尚過曰：「先生苟能使子墨子於越而教寡人，請裂故吳之地，方五百里，以封子墨子。」公尚過許諾。遂為公尚過束車五十乘，以迎子墨子於魯，曰：「吾以夫子之道說越王，越王大說，謂過曰，苟能使子墨子至於越，而教寡人，請裂故吳之地，方五百里，以封子。」子墨子謂公尚過曰：「子觀越王之志何若？意越王將聽吾言，用我道，則翟將往，量腹而食，度身而衣，自比於群臣，奚能以封為哉？抑越不聽吾言，不用吾道，而吾往焉，則是我以義糶也。鈞之糶，亦於中國耳，何必於越哉？」","sentenceIds":["mo-zi_ch-49_p-13_s-1","mo-zi_ch-49_p-13_s-2","mo-zi_ch-49_p-13_s-3","mo-zi_ch-49_p-13_s-4","mo-zi_ch-49_p-13_s-5","mo-zi_ch-49_p-13_s-6","mo-zi_ch-49_p-13_s-7","mo-zi_ch-49_p-13_s-8","mo-zi_ch-49_p-13_s-9"],"sourceRefs":[{"label":"《墨子》—中國哲學書電子化計劃","edition":"孫詒讓《墨子閒詁》本","location":"https://ctext.org/mozi/zh","accessedAt":"2026-08-31"},{"label":"《墨子》—維基文庫","edition":"四部叢刊景明正統道藏本","location":"https://zh.wikisource.org/zh-hant/墨子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"子墨子游公尚過於越。公尚過推理說理越王，越王大推理說理，謂公尚過說道：先生苟能使子墨子於越而且教寡人，請裂所以吳的地，方五百里，以封子墨子。公尚過許諾。遂為公尚過束車五十乘，以迎子墨子於魯，說道：吾以夫子的道推理說理越王，越王大推理說理，謂過說道：，苟能使子墨子至於越，而且教寡人，請裂所以吳的地，方五百里，以封子。子墨子謂公尚過說道：子觀越王的志何若？意越王將聽吾言，用我道，則翟將往，量腹而且食，度身而且衣，自比於群臣，奚能以封為哉？抑越不聽吾言，不用吾道，而且吾往焉，則是我以義糶啊。鈞的糶，亦於中國耳，何必於越哉？","analysis":"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈魯問〉（第 13 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「子墨子游公尚過於越」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「子墨子游公尚過於越。公尚過說越王，越王大說，謂公尚過……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。","historicalContext":"","keywords":[]}},{"id":"mo-zi_ch-49_p-14","chapterId":"mo-zi_ch-49","order":14,"canonicalText":"子墨子游，魏越曰：「既得見四方之君子，則將先語？」子墨子曰：「凡入國，必擇務而從事焉。國家昏亂，則語之尚賢、尚同；國家貧，則語之節用、節葬；國家說音湛湎，則語之非樂、非命；國家遙僻無禮，則語之尊天、事鬼；國家務奪侵凌，即語之兼愛、非攻，故曰擇務而從事焉。」","sentenceIds":["mo-zi_ch-49_p-14_s-1","mo-zi_ch-49_p-14_s-2","mo-zi_ch-49_p-14_s-3","mo-zi_ch-49_p-14_s-4","mo-zi_ch-49_p-14_s-5","mo-zi_ch-49_p-14_s-6","mo-zi_ch-49_p-14_s-7","mo-zi_ch-49_p-14_s-8"],"sourceRefs":[{"label":"《墨子》—中國哲學書電子化計劃","edition":"孫詒讓《墨子閒詁》本","location":"https://ctext.org/mozi/zh","accessedAt":"2026-08-31"},{"label":"《墨子》—維基文庫","edition":"四部叢刊景明正統道藏本","location":"https://zh.wikisource.org/zh-hant/墨子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"子墨子游，魏越說道：既得見四方的君子，則將先語？墨子先生親自教導說道：凡入國，必擇務而且從事焉。國家昏亂，則語的尚賢、上下一心一統政令；國家貧，則語的崇尚節約剋制過度浪費、崇尚薄葬節制奢靡厚葬；國家推理說理音湛湎，則語的絕不是樂、絕不是命；國家遙僻無禮，則語的尊天、事鬼；國家務奪侵凌，即語的天下兼相愛、交相利、絕不是攻，所以墨家典籍評論說道：擇務而且從事焉。","analysis":"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈魯問〉（第 14 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「子墨子游，魏越曰：「既得見四方之君子，則將先語」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「子墨子游，魏越曰：「既得見四方之君子，則將先語？」子……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。","historicalContext":"","keywords":[]}},{"id":"mo-zi_ch-49_p-15","chapterId":"mo-zi_ch-49","order":15,"canonicalText":"子墨子出曹公子而於宋三年而反，睹子墨子曰：「始吾遊於子之門，短褐之衣，藜藿之羹，朝得之，則夕弗得，祭祀鬼神。今而以夫子之教，家厚於始也。有家厚，謹祭祀鬼神。然而人徒多死，六畜不蕃，身湛於病，吾未知夫子之道之可用也。」子墨子曰：「不然！夫鬼神之所欲於人者多，欲人之處高爵祿則以讓賢也，多財則以分貧也。夫鬼神豈唯攫黍拑肺之為欲哉？今子處高爵祿而不以讓賢，一不祥也；多財而不以分貧，二不祥也。今子事鬼神唯祭而已矣，而曰：『病何自至哉？』是猶百門而閉一門焉，曰『盜何從入？』若是而求福於有怪之鬼，豈可哉？」","sentenceIds":["mo-zi_ch-49_p-15_s-1","mo-zi_ch-49_p-15_s-2","mo-zi_ch-49_p-15_s-3","mo-zi_ch-49_p-15_s-4","mo-zi_ch-49_p-15_s-5","mo-zi_ch-49_p-15_s-6","mo-zi_ch-49_p-15_s-7","mo-zi_ch-49_p-15_s-8","mo-zi_ch-49_p-15_s-9","mo-zi_ch-49_p-15_s-10","mo-zi_ch-49_p-15_s-11","mo-zi_ch-49_p-15_s-12","mo-zi_ch-49_p-15_s-13"],"sourceRefs":[{"label":"《墨子》—中國哲學書電子化計劃","edition":"孫詒讓《墨子閒詁》本","location":"https://ctext.org/mozi/zh","accessedAt":"2026-08-31"},{"label":"《墨子》—維基文庫","edition":"四部叢刊景明正統道藏本","location":"https://zh.wikisource.org/zh-hant/墨子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"子墨子出曹公子而且於宋三年而且反，睹墨子先生親自教導說道：始吾遊於子的門，短褐的衣，藜藿的羹，朝得的，則夕弗得，祭祀鬼神。今而且以夫子的教，家厚於始啊。有家厚，謹祭祀鬼神。然而且人徒多死，六畜不蕃，身湛於病，吾未知夫子的道的可用啊。墨子先生親自教導說道：不然！夫鬼神的所欲於人的人多，欲人的處高爵祿則以讓賢啊，多財則以分貧啊。夫鬼神豈唯攫黍拑肺的為欲哉？今子處高爵祿而且不以讓賢，一不祥啊；多財而且不以分貧，二不祥啊。今子事鬼神唯祭而且已矣，而且說道：病何自至哉？是猶百門而且閉一門焉，說道：盜何從入？若是而且求福於有怪的鬼，豈可哉？","analysis":"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈魯問〉（第 15 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「子墨子出曹公子而於宋三年而反，睹子墨子曰：「始吾遊於子之門，短褐之衣，藜藿之羹，朝得之，則夕弗得，祭祀鬼神」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「子墨子出曹公子而於宋三年而反，睹子墨子曰：「始吾遊於……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。","historicalContext":"","keywords":[]}},{"id":"mo-zi_ch-49_p-16","chapterId":"mo-zi_ch-49","order":16,"canonicalText":"魯祝以一豚祭，而求百福於鬼神。子墨子聞之曰：「是不可，今施人薄而望人厚，則人唯恐其有賜於己也。今以一豚祭，而求百福於鬼神，唯恐其以牛羊祀也。古者聖王事鬼神，祭而已矣。今以豚祭而求百福，則其富不如其貧也。」","sentenceIds":["mo-zi_ch-49_p-16_s-1","mo-zi_ch-49_p-16_s-2","mo-zi_ch-49_p-16_s-3","mo-zi_ch-49_p-16_s-4","mo-zi_ch-49_p-16_s-5","mo-zi_ch-49_p-16_s-6"],"sourceRefs":[{"label":"《墨子》—中國哲學書電子化計劃","edition":"孫詒讓《墨子閒詁》本","location":"https://ctext.org/mozi/zh","accessedAt":"2026-08-31"},{"label":"《墨子》—維基文庫","edition":"四部叢刊景明正統道藏本","location":"https://zh.wikisource.org/zh-hant/墨子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"魯祝以一豚祭，而且求百福於鬼神。子墨子聞說道：是不可，今施人薄而且望人厚，則人唯恐他的有賜於己啊。今以一豚祭，而且求百福於鬼神，唯恐他的以牛羊祀啊。古代聖王事鬼神，祭而且已矣。今以豚祭而且求百福，則他的富不如他的貧啊。","analysis":"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈魯問〉（第 16 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「魯祝以一豚祭，而求百福於鬼神」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「魯祝以一豚祭，而求百福於鬼神。子墨子聞之曰：「是不可……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。","historicalContext":"","keywords":[]}},{"id":"mo-zi_ch-49_p-17","chapterId":"mo-zi_ch-49","order":17,"canonicalText":"彭輕生子曰：「往者可知，來者不可知。」子墨子曰：「籍設而親在百里之外，則遇難焉，期以一日也，及之則生，不及則死。今有固車良馬於此，又有奴馬四隅之輪於此，使子擇焉，子將何乘？對曰：「乘良馬固車，可以速至。」子墨子曰：「焉在矣來！」","sentenceIds":["mo-zi_ch-49_p-17_s-1","mo-zi_ch-49_p-17_s-2","mo-zi_ch-49_p-17_s-3","mo-zi_ch-49_p-17_s-4","mo-zi_ch-49_p-17_s-5","mo-zi_ch-49_p-17_s-6"],"sourceRefs":[{"label":"《墨子》—中國哲學書電子化計劃","edition":"孫詒讓《墨子閒詁》本","location":"https://ctext.org/mozi/zh","accessedAt":"2026-08-31"},{"label":"《墨子》—維基文庫","edition":"四部叢刊景明正統道藏本","location":"https://zh.wikisource.org/zh-hant/墨子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"彭輕生子說道：往的人可知，來的人不可知。墨子先生親自教導說道：籍設而且親在百里的外，則遇難焉，期以一日啊，及的則生，不及則死。今有固車良馬於此，又有奴馬四隅的輪於此，使子擇焉，子將何乘？對說道：乘良馬固車，可以速至。墨子先生親自教導說道：焉在矣來！","analysis":"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈魯問〉（第 17 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「彭輕生子曰：「往者可知，來者不可知」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「彭輕生子曰：「往者可知，來者不可知。」子墨子曰：「籍……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。","historicalContext":"","keywords":[]}},{"id":"mo-zi_ch-49_p-18","chapterId":"mo-zi_ch-49","order":18,"canonicalText":"孟山譽王子閭曰：「昔白公之禍，執王子閭斧鉞鉤要，直兵當心，謂之曰：『為王則生，不為王則死。』王子閭曰：『何其侮我也！殺我親而喜我以楚國，我得天下而不義，不為也，又況於楚國乎？』遂而不為。王子閭豈不仁哉？」子墨子曰：「難則難矣，然而未仁也。若以王為無道，則何故不受而治也？若以白公為不義，何故不受王，誅白公然而反王？故曰難則難矣，然而未仁也。」","sentenceIds":["mo-zi_ch-49_p-18_s-1","mo-zi_ch-49_p-18_s-2","mo-zi_ch-49_p-18_s-3","mo-zi_ch-49_p-18_s-4","mo-zi_ch-49_p-18_s-5","mo-zi_ch-49_p-18_s-6","mo-zi_ch-49_p-18_s-7","mo-zi_ch-49_p-18_s-8","mo-zi_ch-49_p-18_s-9","mo-zi_ch-49_p-18_s-10"],"sourceRefs":[{"label":"《墨子》—中國哲學書電子化計劃","edition":"孫詒讓《墨子閒詁》本","location":"https://ctext.org/mozi/zh","accessedAt":"2026-08-31"},{"label":"《墨子》—維基文庫","edition":"四部叢刊景明正統道藏本","location":"https://zh.wikisource.org/zh-hant/墨子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"孟山譽王子閭說道：昔白公的禍，執王子閭斧鉞鉤要，直兵當心，謂說道：為王則生，不為王則死。王子閭說道：何他的侮我啊！殺我親而且喜我以楚國，我得天下而且不義，不為啊，又況於楚國乎？遂而且不為。王子閭豈不仁哉？墨子先生親自教導說道：難則難矣，然而且未仁啊。若以王為無道，則何所以不受而且治啊？若以白公為不義，何所以不受王，誅白公然而且反王？所以墨家典籍評論說道：難則難矣，然而且未仁啊。","analysis":"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈魯問〉（第 18 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「孟山譽王子閭曰：「昔白公之禍，執王子閭斧鉞鉤要，直兵當心，謂之曰：『為王則生，不為王則死」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「孟山譽王子閭曰：「昔白公之禍，執王子閭斧鉞鉤要，直兵……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。","historicalContext":"","keywords":[]}},{"id":"mo-zi_ch-49_p-19","chapterId":"mo-zi_ch-49","order":19,"canonicalText":"子墨子使勝綽事項子牛。項子牛三侵魯地，而勝綽三從。子墨子聞之，使高孫子請而退之曰：「我使綽也，將以濟驕而正嬖也。今綽也祿厚而譎夫子，夫子三侵魯，而綽三從，是鼓鞭於馬靳也。翟聞之：『言義而弗行，是犯明也。』綽非弗之知也，祿勝義也。」","sentenceIds":["mo-zi_ch-49_p-19_s-1","mo-zi_ch-49_p-19_s-2","mo-zi_ch-49_p-19_s-3","mo-zi_ch-49_p-19_s-4","mo-zi_ch-49_p-19_s-5","mo-zi_ch-49_p-19_s-6","mo-zi_ch-49_p-19_s-7"],"sourceRefs":[{"label":"《墨子》—中國哲學書電子化計劃","edition":"孫詒讓《墨子閒詁》本","location":"https://ctext.org/mozi/zh","accessedAt":"2026-08-31"},{"label":"《墨子》—維基文庫","edition":"四部叢刊景明正統道藏本","location":"https://zh.wikisource.org/zh-hant/墨子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"子墨子使勝綽事項子牛。項子牛三侵魯地，而且勝綽三從。子墨子聞的，使高孫子請而且退說道：我使綽啊，將以濟驕而且正嬖啊。今綽啊祿厚而且譎夫子，夫子三侵魯，而且綽三從，是鼓鞭於馬靳啊。翟聞的：言義而且弗行，是犯明啊。綽絕不是弗的知啊，祿勝義啊。","analysis":"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈魯問〉（第 19 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「子墨子使勝綽事項子牛」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「子墨子使勝綽事項子牛。項子牛三侵魯地，而勝綽三從。子……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。","historicalContext":"","keywords":[]}},{"id":"mo-zi_ch-49_p-20","chapterId":"mo-zi_ch-49","order":20,"canonicalText":"昔者楚人與越人舟戰於江，楚人順流而進，迎流而退，見利而進，見不利則其退難。越人迎流而進，順流而退，見利而進，見不利則其退速，越人因此若埶，亟敗楚人。公輸子自魯南遊楚，焉始為舟戰之器，作為鉤強之備，退者鉤之，進者強之，量其鉤強之長，而制為之兵，楚之兵節，越之兵不節，楚人因此若埶，亟敗越人。公輸子善其巧，以語子墨子曰：「我舟戰有鉤強，不知子之義亦有鉤強乎？」子墨子曰：「我義之鉤強，賢於子舟戰之鉤強。我鉤強，我鉤之以愛，揣之以恭。弗鉤以愛，則不親；弗揣以恭，則速狎；狎而不親則速離。故交相愛，交相恭，猶若相利也。今子鉤而止人，人亦鉤而止子，子強而距人，人亦強而距子，交相鉤，交相強，猶若相害也。故我義之鉤強，賢子舟戰之鉤強。」","sentenceIds":["mo-zi_ch-49_p-20_s-1","mo-zi_ch-49_p-20_s-2","mo-zi_ch-49_p-20_s-3","mo-zi_ch-49_p-20_s-4","mo-zi_ch-49_p-20_s-5","mo-zi_ch-49_p-20_s-6","mo-zi_ch-49_p-20_s-7","mo-zi_ch-49_p-20_s-8","mo-zi_ch-49_p-20_s-9","mo-zi_ch-49_p-20_s-10","mo-zi_ch-49_p-20_s-11","mo-zi_ch-49_p-20_s-12","mo-zi_ch-49_p-20_s-13"],"sourceRefs":[{"label":"《墨子》—中國哲學書電子化計劃","edition":"孫詒讓《墨子閒詁》本","location":"https://ctext.org/mozi/zh","accessedAt":"2026-08-31"},{"label":"《墨子》—維基文庫","edition":"四部叢刊景明正統道藏本","location":"https://zh.wikisource.org/zh-hant/墨子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"昔日楚人與越人舟戰於江，楚人順流而且進，迎流而且退，見利而且進，見不利則他的退難。越人迎流而且進，順流而且退，見利而且進，見不利則他的退速，越人因此若埶，亟敗楚人。公輸子自魯南遊楚，焉始為舟戰的器，作為鉤強的備，退的人鉤的，進的人強的，量他的鉤強的長，而且制為的兵，楚的兵節，越的兵不節，楚人因此若埶，亟敗越人。公輸子善他的巧，以語墨子先生親自教導說道：我舟戰有鉤強，不知子的義亦有鉤強乎？墨子先生親自教導說道：我義的鉤強，賢於子舟戰的鉤強。我鉤強，我鉤的以愛，揣的以恭。弗鉤以愛，則不親；弗揣以恭，則速狎；狎而且不親則速離。所以交相愛，交相恭，猶若相利啊。今子鉤而且止人，人亦鉤而且止子，子強而且距人，人亦強而且距子，交相鉤，交相強，猶若相害啊。所以我義的鉤強，賢子舟戰的鉤強。","analysis":"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈魯問〉（第 20 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「昔者楚人與越人舟戰於江，楚人順流而進，迎流而退，見利而進，見不利則其退難」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「昔者楚人與越人舟戰於江，楚人順流而進，迎流而退，見利……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。","historicalContext":"","keywords":[]}},{"id":"mo-zi_ch-49_p-21","chapterId":"mo-zi_ch-49","order":21,"canonicalText":"公輸子削竹木以為鵲，成而飛之，三日不下，公輸子自以為至巧。子墨子謂公輸子曰：「子之為鵲也，不如匠之為車轄。須臾劉三寸之木，而任五十石之重。故所為功，利於人謂之巧，不利於人謂之拙。」","sentenceIds":["mo-zi_ch-49_p-21_s-1","mo-zi_ch-49_p-21_s-2","mo-zi_ch-49_p-21_s-3","mo-zi_ch-49_p-21_s-4","mo-zi_ch-49_p-21_s-5"],"sourceRefs":[{"label":"《墨子》—中國哲學書電子化計劃","edition":"孫詒讓《墨子閒詁》本","location":"https://ctext.org/mozi/zh","accessedAt":"2026-08-31"},{"label":"《墨子》—維基文庫","edition":"四部叢刊景明正統道藏本","location":"https://zh.wikisource.org/zh-hant/墨子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"公輸子削竹木以為鵲，成而且飛的，三日不下，公輸子自以為至巧。子墨子謂公輸子說道：子的為鵲啊，不如匠的為車轄。須臾劉三寸的木，而且任五十石的重。所以所為功，利於人謂的巧，不利於人謂的拙。","analysis":"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈魯問〉（第 21 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「公輸子削竹木以為鵲，成而飛之，三日不下，公輸子自以為至巧」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「公輸子削竹木以為鵲，成而飛之，三日不下，公輸子自以為……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。","historicalContext":"","keywords":[]}},{"id":"mo-zi_ch-49_p-22","chapterId":"mo-zi_ch-49","order":22,"canonicalText":"公輸子謂子墨子曰：「吾未得見之時，我欲得宋，自我得見之後，予我宋而不義，我不為。」子墨子曰：「翟之未得見之時也，子欲得宋，自翟得見子之後，予子宋而不義，子弗為，是我予子宋也。子務為義，翟又將予子天下。」","sentenceIds":["mo-zi_ch-49_p-22_s-1","mo-zi_ch-49_p-22_s-2","mo-zi_ch-49_p-22_s-3","mo-zi_ch-49_p-22_s-4"],"sourceRefs":[{"label":"《墨子》—中國哲學書電子化計劃","edition":"孫詒讓《墨子閒詁》本","location":"https://ctext.org/mozi/zh","accessedAt":"2026-08-31"},{"label":"《墨子》—維基文庫","edition":"四部叢刊景明正統道藏本","location":"https://zh.wikisource.org/zh-hant/墨子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"公輸子謂墨子先生親自教導說道：吾未得見的時，我欲得宋，自我得見的後，予我宋而且不義，我不為。墨子先生親自教導說道：翟的未得見的時啊，子欲得宋，自翟得見子的後，予子宋而且不義，子弗為，是我予子宋啊。子務為義，翟又將予子天下。","analysis":"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈魯問〉（第 22 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「公輸子謂子墨子曰：「吾未得見之時，我欲得宋，自我得見之後，予我宋而不義，我不為」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「公輸子謂子墨子曰：「吾未得見之時，我欲得宋，自我得見……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。","historicalContext":"","keywords":[]}}],"sentences":[{"id":"mo-zi_ch-49_p-1_s-1","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-1","order":1,"canonicalText":"魯君謂子墨子曰：「吾恐齊之攻我也，可救乎？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-1_s-2","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-1","order":2,"canonicalText":"」子墨子曰：「可。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-1_s-3","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-1","order":3,"canonicalText":"昔者，三代之聖王禹湯文武，百里之諸侯也，說忠行義，取天下。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-1_s-4","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-1","order":4,"canonicalText":"三代之暴王桀紂幽厲，讎怨行暴，失天下。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-1_s-5","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-1","order":5,"canonicalText":"吾願主君，之上者尊天事鬼，下者愛利百姓，厚為皮幣，卑辭令，亟遍禮四鄰諸侯，敺國而以事齊，患可救也，非此，顧無可為者。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-1_s-6","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-1","order":6,"canonicalText":"」","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-2_s-1","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-2","order":1,"canonicalText":"齊將伐魯，子墨子謂項子牛曰：「伐魯，齊之大過也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-2_s-2","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-2","order":2,"canonicalText":"昔者，吳王東伐越，棲諸會稽，西伐楚，葆昭王於隨。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-2_s-3","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-2","order":3,"canonicalText":"北伐齊，取國子以歸於吳。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-2_s-4","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-2","order":4,"canonicalText":"諸侯報其讎，百姓苦其勞，而弗為用，是以國為虛戾，身為刑戮也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-2_s-5","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-2","order":5,"canonicalText":"昔者，智伯伐范氏與中行氏，兼三晉之地，諸侯報其讎，百姓苦其勞，而弗為用，是以國為虛戾，身為刑戮用是也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-2_s-6","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-2","order":6,"canonicalText":"故大國之攻小國也，是交相賊也，過必反於國。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-2_s-7","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-2","order":7,"canonicalText":"」","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-3_s-1","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-3","order":1,"canonicalText":"子墨子見齊大王曰：「今有刀於此，試之人頭，倅然斷之，可謂利乎？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-3_s-2","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-3","order":2,"canonicalText":"」大王曰：「利。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-3_s-3","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-3","order":3,"canonicalText":"」子墨子曰：「多試之人頭，倅然斷之，可謂利乎？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-3_s-4","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-3","order":4,"canonicalText":"」大王曰：「利。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-3_s-5","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-3","order":5,"canonicalText":"」子墨子曰：「刀則利矣，孰將受其不祥？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-3_s-6","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-3","order":6,"canonicalText":"」大王曰：「刀受其利，試者受其不祥。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-3_s-7","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-3","order":7,"canonicalText":"」子墨子曰：「並國覆軍，賊殺百姓，孰將受其不祥？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-3_s-8","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-3","order":8,"canonicalText":"」大王俯仰而思之曰：「我受其不祥。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-3_s-9","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-3","order":9,"canonicalText":"」","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-4_s-1","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-4","order":1,"canonicalText":"魯陽文君將攻鄭，子墨子聞而止之，謂陽文君曰：「今使魯四境之內，大都攻其小都，大家伐其小家，殺其人民，取其牛馬狗豕布帛米粟貨財，則何若？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-4_s-2","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-4","order":2,"canonicalText":"」魯陽文君曰：「魯四境之內，皆寡人之臣也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-4_s-3","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-4","order":3,"canonicalText":"今大都攻其小都，大家伐其小家，奪之貨財，則寡人必將厚罰之。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-4_s-4","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-4","order":4,"canonicalText":"」子墨子曰：「夫天之兼有天下也，亦猶君之有四境之內也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-4_s-5","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-4","order":5,"canonicalText":"今舉兵將以攻鄭，天誅亓不至乎？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-4_s-6","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-4","order":6,"canonicalText":"」魯陽文君曰：「先生何止我攻鄭也？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-4_s-7","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-4","order":7,"canonicalText":"我攻鄭，順於天之志。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-4_s-8","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-4","order":8,"canonicalText":"鄭人三世殺其父，天加誅焉，使三年不全。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-4_s-9","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-4","order":9,"canonicalText":"我將助天誅也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-4_s-10","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-4","order":10,"canonicalText":"」子墨子曰：「鄭人三世殺其父而天加誅焉，使三年不全。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-4_s-11","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-4","order":11,"canonicalText":"天誅足矣，今又舉兵將以攻鄭，曰『吾攻鄭也，順於天之志』。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-4_s-12","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-4","order":12,"canonicalText":"譬有人於此，其子強梁不材，故其父笞之，其鄰家之父舉木而擊之，曰：『吾擊之也，順於其父之志』，則豈不悖哉？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-4_s-13","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-4","order":13,"canonicalText":"」","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-5_s-1","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-5","order":1,"canonicalText":"子墨子謂魯陽文君曰：「攻其鄰國，殺其民人，取其牛馬、粟米、貨財，則書之於竹帛，鏤之於金石，以為銘於鍾鼎，傳遺後世子孫曰：『莫若我多。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-5_s-2","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-5","order":2,"canonicalText":"』今賤人也，亦攻其鄰家，殺其人民，取其狗豕食糧衣裘，亦書之竹帛，以為銘於席豆，以遺後世子孫曰：『莫若我多。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-5_s-3","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-5","order":3,"canonicalText":"』亓可乎？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-5_s-4","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-5","order":4,"canonicalText":"」魯陽文君曰：「然吾以子之言觀之，則天下之所謂可者，未必然也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-5_s-5","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-5","order":5,"canonicalText":"」","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-6_s-1","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-6","order":1,"canonicalText":"子墨子為魯陽文君曰：「世俗之君子，皆知小物而不知大物。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-6_s-2","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-6","order":2,"canonicalText":"今有人於此，竊一犬一彘則謂之不仁，竊一國一都則以為義。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-6_s-3","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-6","order":3,"canonicalText":"譬猶小視白謂之白，大視白則謂之黑。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-6_s-4","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-6","order":4,"canonicalText":"是故世俗之君子，知小物而不知大物者，此若言之謂也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-6_s-5","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-6","order":5,"canonicalText":"」","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-7_s-1","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-7","order":1,"canonicalText":"魯陽文君語子墨子曰：「楚之南有啖人之國者橋，其國之長子生，則鮮而食之，謂之宜弟。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-7_s-2","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-7","order":2,"canonicalText":"美，則以遺其君，君喜則賞其父。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-7_s-3","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-7","order":3,"canonicalText":"豈不惡俗哉？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-7_s-4","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-7","order":4,"canonicalText":"」子墨子曰：「雖中國之俗，亦猶是也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-7_s-5","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-7","order":5,"canonicalText":"殺其父而賞其子，何以異食其子而賞其父者哉？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-7_s-6","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-7","order":6,"canonicalText":"苟不用仁義，何以非夷人食其子也？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-7_s-7","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-7","order":7,"canonicalText":"」","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-8_s-1","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-8","order":1,"canonicalText":"魯君之嬖人死，魯君為之誄，魯人因說而用之。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-8_s-2","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-8","order":2,"canonicalText":"子墨子聞之曰：「誄者，道死人之志也，今因說而用之，是猶以來首從服也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-8_s-3","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-8","order":3,"canonicalText":"」","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-9_s-1","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-9","order":1,"canonicalText":"魯陽文君謂子墨子曰：「有語我以忠臣者，令之俯則俯，令之仰則仰，處則靜，呼則應，可謂忠臣乎？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-9_s-2","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-9","order":2,"canonicalText":"」子墨子曰：「令之俯則俯，令之仰則仰，是似景也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-9_s-3","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-9","order":3,"canonicalText":"處則靜，呼則應，是似響也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-9_s-4","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-9","order":4,"canonicalText":"君將何得於景與響哉？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-9_s-5","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-9","order":5,"canonicalText":"若以翟之所謂忠臣者，上有過則微之以諫，己有善，則訪之上，而無敢以告。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-9_s-6","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-9","order":6,"canonicalText":"外匡其邪，而入其善，尚同而無下比，是以美善在上，而怨讎在下，安樂在上，而憂慼在臣。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-9_s-7","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-9","order":7,"canonicalText":"此翟之所謂忠臣者也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-9_s-8","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-9","order":8,"canonicalText":"」","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-10_s-1","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-10","order":1,"canonicalText":"魯君謂子墨子曰：「我有二子，一人者好學，一人者好分人財，孰以為太子而可？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-10_s-2","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-10","order":2,"canonicalText":"」子墨子曰：「未可知也，或所為賞與為是也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-10_s-3","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-10","order":3,"canonicalText":"魡者之恭，非為魚賜也；","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-10_s-4","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-10","order":4,"canonicalText":"餌鼠以蟲，非愛之也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-10_s-5","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-10","order":5,"canonicalText":"吾願主君之合其志功而觀焉。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-10_s-6","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-10","order":6,"canonicalText":"」","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-11_s-1","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-11","order":1,"canonicalText":"魯人有因子墨子而學其子者，其子戰而死，其父讓子墨子。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-11_s-2","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-11","order":2,"canonicalText":"子墨子曰：子欲學子之子，今學成矣，戰而死，而子慍，而猶欲糶，糶讎，則慍也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-11_s-3","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-11","order":3,"canonicalText":"豈不費哉？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-11_s-4","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-11","order":4,"canonicalText":"」","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-12_s-1","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-12","order":1,"canonicalText":"魯之南鄙人，有吳慮者，冬陶夏耕，自比於舜。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-12_s-2","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-12","order":2,"canonicalText":"子墨子聞而見之。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-12_s-3","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-12","order":3,"canonicalText":"吳慮謂子墨子「義耳義耳，焉用言之哉？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-12_s-4","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-12","order":4,"canonicalText":"」子墨子曰：「子之所謂義者，亦有力以勞人，有財以分人乎？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-12_s-5","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-12","order":5,"canonicalText":"」吳慮曰：「有。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-12_s-6","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-12","order":6,"canonicalText":"」子墨子曰：「翟嘗計之矣。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-12_s-7","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-12","order":7,"canonicalText":"翟慮耕而食天下之人矣，盛，然後當一農之耕，分諸天下，不能人得一升粟。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-12_s-8","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-12","order":8,"canonicalText":"籍而以為得一升粟，其不能飽天下之飢者，既可睹矣。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-12_s-9","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-12","order":9,"canonicalText":"翟慮織而衣天下之人矣，盛，然後當一婦人之織，分諸天下，不能人得尺布。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-12_s-10","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-12","order":10,"canonicalText":"籍而以為得尺布，其不能煖天下之寒者，既可睹矣。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-12_s-11","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-12","order":11,"canonicalText":"翟慮被堅執銳救諸侯之患，盛，然後當一夫之戰，一夫之戰其不御三軍，既可睹矣。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-12_s-12","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-12","order":12,"canonicalText":"翟以為不若誦先王之道，而求其說，通聖人之言，而察其辭，上說王公大人，次匹夫徒步之士。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-12_s-13","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-12","order":13,"canonicalText":"王公大人用吾言，國必治；","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-12_s-14","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-12","order":14,"canonicalText":"匹夫徒步之士用吾言，行必脩。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-12_s-15","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-12","order":15,"canonicalText":"故翟以為雖不耕而食飢，不織而衣寒，功賢於耕而食之、織而衣之者也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-12_s-16","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-12","order":16,"canonicalText":"故翟以為雖不耕織乎，而功賢於耕織也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-12_s-17","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-12","order":17,"canonicalText":"」吳慮謂子墨子曰：「義耳義耳，焉用言之哉？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-12_s-18","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-12","order":18,"canonicalText":"」子墨子曰：「籍設而天下不知耕，教人耕，與不教人耕而獨耕者，其功孰多？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-12_s-19","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-12","order":19,"canonicalText":"」吳慮曰：「教人耕者其功多。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-12_s-20","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-12","order":20,"canonicalText":"」子墨子曰：「籍設而攻不義之國，鼓而使眾進戰，與不鼓而使眾進戰，而獨進戰者，其功孰多？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-12_s-21","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-12","order":21,"canonicalText":"」吳慮曰：「鼓而進眾者其功多。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-12_s-22","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-12","order":22,"canonicalText":"」子墨子曰：「天下匹夫徒步之士，少知義而教天下以義者，功亦多，何故弗言也？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-12_s-23","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-12","order":23,"canonicalText":"若得鼓而進於義，則吾義豈不益進哉？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-12_s-24","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-12","order":24,"canonicalText":"」","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-13_s-1","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-13","order":1,"canonicalText":"子墨子游公尚過於越。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-13_s-2","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-13","order":2,"canonicalText":"公尚過說越王，越王大說，謂公尚過曰：「先生苟能使子墨子於越而教寡人，請裂故吳之地，方五百里，以封子墨子。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-13_s-3","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-13","order":3,"canonicalText":"」公尚過許諾。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-13_s-4","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-13","order":4,"canonicalText":"遂為公尚過束車五十乘，以迎子墨子於魯，曰：「吾以夫子之道說越王，越王大說，謂過曰，苟能使子墨子至於越，而教寡人，請裂故吳之地，方五百里，以封子。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-13_s-5","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-13","order":5,"canonicalText":"」子墨子謂公尚過曰：「子觀越王之志何若？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-13_s-6","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-13","order":6,"canonicalText":"意越王將聽吾言，用我道，則翟將往，量腹而食，度身而衣，自比於群臣，奚能以封為哉？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-13_s-7","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-13","order":7,"canonicalText":"抑越不聽吾言，不用吾道，而吾往焉，則是我以義糶也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-13_s-8","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-13","order":8,"canonicalText":"鈞之糶，亦於中國耳，何必於越哉？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-13_s-9","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-13","order":9,"canonicalText":"」","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-14_s-1","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-14","order":1,"canonicalText":"子墨子游，魏越曰：「既得見四方之君子，則將先語？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-14_s-2","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-14","order":2,"canonicalText":"」子墨子曰：「凡入國，必擇務而從事焉。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-14_s-3","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-14","order":3,"canonicalText":"國家昏亂，則語之尚賢、尚同；","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-14_s-4","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-14","order":4,"canonicalText":"國家貧，則語之節用、節葬；","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-14_s-5","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-14","order":5,"canonicalText":"國家說音湛湎，則語之非樂、非命；","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-14_s-6","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-14","order":6,"canonicalText":"國家遙僻無禮，則語之尊天、事鬼；","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-14_s-7","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-14","order":7,"canonicalText":"國家務奪侵凌，即語之兼愛、非攻，故曰擇務而從事焉。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-14_s-8","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-14","order":8,"canonicalText":"」","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-15_s-1","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-15","order":1,"canonicalText":"子墨子出曹公子而於宋三年而反，睹子墨子曰：「始吾遊於子之門，短褐之衣，藜藿之羹，朝得之，則夕弗得，祭祀鬼神。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-15_s-2","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-15","order":2,"canonicalText":"今而以夫子之教，家厚於始也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-15_s-3","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-15","order":3,"canonicalText":"有家厚，謹祭祀鬼神。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-15_s-4","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-15","order":4,"canonicalText":"然而人徒多死，六畜不蕃，身湛於病，吾未知夫子之道之可用也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-15_s-5","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-15","order":5,"canonicalText":"」子墨子曰：「不然！","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-15_s-6","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-15","order":6,"canonicalText":"夫鬼神之所欲於人者多，欲人之處高爵祿則以讓賢也，多財則以分貧也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-15_s-7","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-15","order":7,"canonicalText":"夫鬼神豈唯攫黍拑肺之為欲哉？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-15_s-8","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-15","order":8,"canonicalText":"今子處高爵祿而不以讓賢，一不祥也；","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-15_s-9","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-15","order":9,"canonicalText":"多財而不以分貧，二不祥也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-15_s-10","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-15","order":10,"canonicalText":"今子事鬼神唯祭而已矣，而曰：『病何自至哉？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-15_s-11","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-15","order":11,"canonicalText":"』是猶百門而閉一門焉，曰『盜何從入？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-15_s-12","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-15","order":12,"canonicalText":"』若是而求福於有怪之鬼，豈可哉？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-15_s-13","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-15","order":13,"canonicalText":"」","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-16_s-1","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-16","order":1,"canonicalText":"魯祝以一豚祭，而求百福於鬼神。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-16_s-2","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-16","order":2,"canonicalText":"子墨子聞之曰：「是不可，今施人薄而望人厚，則人唯恐其有賜於己也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-16_s-3","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-16","order":3,"canonicalText":"今以一豚祭，而求百福於鬼神，唯恐其以牛羊祀也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-16_s-4","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-16","order":4,"canonicalText":"古者聖王事鬼神，祭而已矣。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-16_s-5","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-16","order":5,"canonicalText":"今以豚祭而求百福，則其富不如其貧也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-16_s-6","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-16","order":6,"canonicalText":"」","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-17_s-1","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-17","order":1,"canonicalText":"彭輕生子曰：「往者可知，來者不可知。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-17_s-2","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-17","order":2,"canonicalText":"」子墨子曰：「籍設而親在百里之外，則遇難焉，期以一日也，及之則生，不及則死。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-17_s-3","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-17","order":3,"canonicalText":"今有固車良馬於此，又有奴馬四隅之輪於此，使子擇焉，子將何乘？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-17_s-4","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-17","order":4,"canonicalText":"對曰：「乘良馬固車，可以速至。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-17_s-5","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-17","order":5,"canonicalText":"」子墨子曰：「焉在矣來！","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-17_s-6","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-17","order":6,"canonicalText":"」","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-18_s-1","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-18","order":1,"canonicalText":"孟山譽王子閭曰：「昔白公之禍，執王子閭斧鉞鉤要，直兵當心，謂之曰：『為王則生，不為王則死。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-18_s-2","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-18","order":2,"canonicalText":"』王子閭曰：『何其侮我也！","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-18_s-3","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-18","order":3,"canonicalText":"殺我親而喜我以楚國，我得天下而不義，不為也，又況於楚國乎？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-18_s-4","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-18","order":4,"canonicalText":"』遂而不為。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-18_s-5","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-18","order":5,"canonicalText":"王子閭豈不仁哉？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-18_s-6","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-18","order":6,"canonicalText":"」子墨子曰：「難則難矣，然而未仁也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-18_s-7","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-18","order":7,"canonicalText":"若以王為無道，則何故不受而治也？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-18_s-8","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-18","order":8,"canonicalText":"若以白公為不義，何故不受王，誅白公然而反王？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-18_s-9","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-18","order":9,"canonicalText":"故曰難則難矣，然而未仁也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-18_s-10","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-18","order":10,"canonicalText":"」","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-19_s-1","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-19","order":1,"canonicalText":"子墨子使勝綽事項子牛。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-19_s-2","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-19","order":2,"canonicalText":"項子牛三侵魯地，而勝綽三從。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-19_s-3","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-19","order":3,"canonicalText":"子墨子聞之，使高孫子請而退之曰：「我使綽也，將以濟驕而正嬖也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-19_s-4","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-19","order":4,"canonicalText":"今綽也祿厚而譎夫子，夫子三侵魯，而綽三從，是鼓鞭於馬靳也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-19_s-5","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-19","order":5,"canonicalText":"翟聞之：『言義而弗行，是犯明也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-19_s-6","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-19","order":6,"canonicalText":"』綽非弗之知也，祿勝義也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-19_s-7","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-19","order":7,"canonicalText":"」","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-20_s-1","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-20","order":1,"canonicalText":"昔者楚人與越人舟戰於江，楚人順流而進，迎流而退，見利而進，見不利則其退難。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-20_s-2","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-20","order":2,"canonicalText":"越人迎流而進，順流而退，見利而進，見不利則其退速，越人因此若埶，亟敗楚人。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-20_s-3","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-20","order":3,"canonicalText":"公輸子自魯南遊楚，焉始為舟戰之器，作為鉤強之備，退者鉤之，進者強之，量其鉤強之長，而制為之兵，楚之兵節，越之兵不節，楚人因此若埶，亟敗越人。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-20_s-4","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-20","order":4,"canonicalText":"公輸子善其巧，以語子墨子曰：「我舟戰有鉤強，不知子之義亦有鉤強乎？","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-20_s-5","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-20","order":5,"canonicalText":"」子墨子曰：「我義之鉤強，賢於子舟戰之鉤強。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-20_s-6","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-20","order":6,"canonicalText":"我鉤強，我鉤之以愛，揣之以恭。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-20_s-7","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-20","order":7,"canonicalText":"弗鉤以愛，則不親；","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-20_s-8","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-20","order":8,"canonicalText":"弗揣以恭，則速狎；","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-20_s-9","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-20","order":9,"canonicalText":"狎而不親則速離。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-20_s-10","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-20","order":10,"canonicalText":"故交相愛，交相恭，猶若相利也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-20_s-11","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-20","order":11,"canonicalText":"今子鉤而止人，人亦鉤而止子，子強而距人，人亦強而距子，交相鉤，交相強，猶若相害也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-20_s-12","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-20","order":12,"canonicalText":"故我義之鉤強，賢子舟戰之鉤強。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-20_s-13","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-20","order":13,"canonicalText":"」","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-21_s-1","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-21","order":1,"canonicalText":"公輸子削竹木以為鵲，成而飛之，三日不下，公輸子自以為至巧。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-21_s-2","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-21","order":2,"canonicalText":"子墨子謂公輸子曰：「子之為鵲也，不如匠之為車轄。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-21_s-3","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-21","order":3,"canonicalText":"須臾劉三寸之木，而任五十石之重。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-21_s-4","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-21","order":4,"canonicalText":"故所為功，利於人謂之巧，不利於人謂之拙。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-21_s-5","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-21","order":5,"canonicalText":"」","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-22_s-1","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-22","order":1,"canonicalText":"公輸子謂子墨子曰：「吾未得見之時，我欲得宋，自我得見之後，予我宋而不義，我不為。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-22_s-2","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-22","order":2,"canonicalText":"」子墨子曰：「翟之未得見之時也，子欲得宋，自翟得見子之後，予子宋而不義，子弗為，是我予子宋也。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-22_s-3","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-22","order":3,"canonicalText":"子務為義，翟又將予子天下。","chunks":[],"tags":[]},{"id":"mo-zi_ch-49_p-22_s-4","workId":"mo-zi","chapterId":"mo-zi_ch-49","passageId":"mo-zi_ch-49_p-22","order":4,"canonicalText":"」","chunks":[],"tags":[]}]}');export{o as default};
